def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # For each 2x2 block, cycle the four diagonal marker colors clockwise:
    # NW receives SW, NE receives NW, SW receives SE, SE receives NE.
    # Extend each recolored corner diagonally outward to the grid edge.
    for r in range(h-1):
        for c in range(w-1):
            if not (grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2):
                continue
            corners=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
            if not all(0<=rr<h and 0<=cc<w for rr,cc in corners):
                continue
            nw,ne,sw,se=(grid[rr][cc] for rr,cc in corners)
            rays=[(corners[0],sw,-1,-1),(corners[1],nw,-1,1),
                  (corners[2],se,1,-1),(corners[3],ne,1,1)]
            for (sr,sc),color,dr,dc in rays:
                if grid[sr][sc] not in (3,6,7,8) or color not in (3,6,7,8):
                    continue
                rr,cc=sr,sc
                while 0<=rr<h and 0<=cc<w:
                    if grid[rr][cc]!=2:
                        out[rr][cc]=color
                    rr+=dr;cc+=dc
    return out
